package service

import (
	"context"
	"errors"
	"fmt"
	"net/url"

	"github.com/Bob-xisuke/orb-scheduler-core/internal/model"
)

// Query business errors, both recognizable with errors.Is.
var (
	// ErrInvalidPlacementQuery is returned when the parameter set is not one
	// of the documented combinations. Validation happens before any storage
	// access, so an invalid query never reaches the model.
	ErrInvalidPlacementQuery = errors.New("invalid placement query")
	// ErrPlacementNotFound is returned by the single-record form when the
	// (namespace, name) identity is unknown.
	ErrPlacementNotFound = errors.New("placement not found")
)

// QueryResult carries the outcome of Query. Exactly one field is non-nil on
// success: Record for the single-record form, Items for the list form. On
// failure both are nil. Items is never nil on a successful list, even when
// nothing matched.
type QueryResult struct {
	Record *model.Placement
	Items  []*model.Placement
}

// Query is the transport-independent read entry point. values holds the
// already-decoded query parameters with duplicates preserved; it is only
// read, never modified, and its values are matched exactly as given — no
// trimming and no further decoding.
//
// Only the four documented keys are accepted. With name, namespace is the
// only other allowed key and the result is the single stored record or
// ErrPlacementNotFound. Without name, namespace, queue and node intersect as
// filters, omitted conditions are ignored, and a nil or empty set lists
// everything. Lists are ordered by namespace then name in UTF-8 byte order;
// a node filter never matches a rejected record. Unknown keys, repeated or
// empty values and illegal combinations yield ErrInvalidPlacementQuery, and
// any persistence failure yields ErrStorageUnavailable.
func (s *Service) Query(ctx context.Context, values url.Values) (QueryResult, error) {
	params, err := validateQuery(values)
	if err != nil {
		return QueryResult{}, err
	}

	if name, hasName := params["name"]; hasName {
		rec, err := s.st.Get(ctx, params["namespace"], name)
		if errors.Is(err, model.ErrNotFound) {
			return QueryResult{}, fmt.Errorf("query placement: %w", ErrPlacementNotFound)
		}
		if err != nil {
			return QueryResult{}, queryStorageError(err)
		}
		return QueryResult{Record: rec}, nil
	}

	recs, err := s.st.List(ctx, model.ListFilter{
		Namespace: params["namespace"],
		Queue:     params["queue"],
		Node:      params["node"],
	})
	if err != nil {
		return QueryResult{}, queryStorageError(err)
	}
	if recs == nil {
		recs = []*model.Placement{}
	}
	return QueryResult{Items: recs}, nil
}

var allowedQueryKeys = map[string]bool{
	"namespace": true,
	"name":      true,
	"queue":     true,
	"node":      true,
}

// validateQuery accepts only the four documented keys, each exactly once with
// a non-empty value, and only the documented combinations: name requires
// namespace and forbids queue and node.
func validateQuery(values url.Values) (map[string]string, error) {
	params := make(map[string]string, len(values))
	for key, vals := range values {
		if !allowedQueryKeys[key] || len(vals) != 1 || vals[0] == "" {
			return nil, fmt.Errorf("query placement: %w", ErrInvalidPlacementQuery)
		}
		params[key] = vals[0]
	}
	if _, hasName := params["name"]; hasName {
		_, hasNamespace := params["namespace"]
		_, hasQueue := params["queue"]
		_, hasNode := params["node"]
		if !hasNamespace || hasQueue || hasNode {
			return nil, fmt.Errorf("query placement: %w", ErrInvalidPlacementQuery)
		}
	}
	return params, nil
}

func queryStorageError(err error) error {
	return fmt.Errorf("query placements: %w: %w", ErrStorageUnavailable, err)
}

// Package service implements placement acceptance: the trial scheduling
// decision together with idempotent, conflict-aware registration. Accept is
// the single business entry point for a parsed placement request; it has no
// dependency on the HTTP transport.
package service

import (
	"context"
	"errors"
	"fmt"

	"github.com/Bob-xisuke/orb-scheduler-core/internal/model"
)

// Scheduling outcomes recorded on every placement.
const (
	StatusPlaced   = "placed"
	StatusRejected = "rejected"
	ReasonNoNode   = "no_eligible_node"
)

// Outcome classifies what Accept did with a submission.
type Outcome int

const (
	// Created means the (namespace, name) identity was registered for the
	// first time by this call.
	Created Outcome = iota
	// Identical means the identity already existed with the same request
	// content; the returned record is the original one.
	Identical
	// Conflict means the identity already existed with different content;
	// the returned record is the untouched original.
	Conflict
)

// ErrStorageUnavailable is the sentinel wrapped for every persistence failure.
var ErrStorageUnavailable = errors.New("storage unavailable")

// Service holds the collaborators needed to accept placements.
type Service struct {
	st Store
}

// New builds the acceptance service over a Store. Production callers pass the
// SQLite-backed *store.Store; tests may pass any implementation of the
// contract without changing Accept or Query behavior.
func New(st Store) *Service {
	return &Service{st: st}
}

// Accept runs the trial placement and registers its result under the
// (namespace, name) identity. The first valid submission for an identity is
// stored and reported as Created; a later submission carrying the same request
// content is reported as Identical with the original record; one carrying
// different content is reported as Conflict and never changes the stored
// record. Scheduling results alone do not count as equal content. Input
// validation is expected to have happened before this call.
func (s *Service) Accept(ctx context.Context, p *model.Placement) (*model.Placement, Outcome, error) {
	// Fill omitted-field defaults through the single shared definition so
	// the trial, the stored record and the content comparison all see the
	// same input. The candidate array's order is left untouched.
	model.NormalizeInput(p)
	p.Status, p.Node, p.Reason = schedule(p)

	stored, created, err := s.st.Submit(ctx, p)
	if err != nil {
		return nil, Created, storageError(err)
	}
	if created {
		return stored, Created, nil
	}

	same, err := model.SameInput(p, stored)
	if err != nil {
		return nil, Created, storageError(err)
	}
	if !same {
		return stored, Conflict, nil
	}
	return stored, Identical, nil
}

func storageError(err error) error {
	return fmt.Errorf("accept placement: %w: %w", ErrStorageUnavailable, err)
}

package api

import (
	"errors"
	"io"
	"net/http"
	"net/url"

	"github.com/gin-gonic/gin"

	"github.com/Bob-xisuke/orb-scheduler-core/internal/placement"
	"github.com/Bob-xisuke/orb-scheduler-core/internal/service"
)

// Error codes published by the placements API.
const (
	codeInvalidInput = "InvalidPlacementInputError"
	codeNotFound     = "PlacementNotFoundError"
	codeConflict     = "PlacementConflictError"
	codeStorageDown  = "storage_unavailable"
)

type placementHandler struct {
	svc *service.Service
}

func writeAPIError(c *gin.Context, status int, code, message string) {
	c.AbortWithStatusJSON(status, gin.H{"error": gin.H{"code": code, "message": message}})
}

// createPlacement handles POST /v1/placements. The transport layer only
// parses and validates the request and maps the business acceptance outcome
// to its HTTP status; scheduling and idempotency/conflict decisions belong to
// service.Accept. The strict parsing rules live in package placement and are
// shared with direct, non-HTTP callers.
func (h *placementHandler) createPlacement(c *gin.Context) {
	body, err := io.ReadAll(c.Request.Body)
	if err != nil {
		writeAPIError(c, http.StatusBadRequest, codeInvalidInput, "invalid placement input")
		return
	}
	p, err := placement.ParsePlacementInput(body)
	if err != nil {
		writeAPIError(c, http.StatusBadRequest, codeInvalidInput, "invalid placement input")
		return
	}

	stored, outcome, err := h.svc.Accept(c.Request.Context(), p)
	if err != nil {
		writeAPIError(c, http.StatusServiceUnavailable, codeStorageDown, "database is not available")
		return
	}
	switch outcome {
	case service.Created:
		c.JSON(http.StatusCreated, stored)
	case service.Identical:
		c.JSON(http.StatusOK, stored)
	case service.Conflict:
		writeAPIError(c, http.StatusConflict, codeConflict,
			"a placement with this namespace and name already exists with different content")
	}
}

// listPlacements handles GET /v1/placements, both the single-record form
// (namespace+name) and the filtered-list form. The transport layer only
// decodes the raw query string and maps the business result to its HTTP
// status; all parameter rules and filtering belong to service.Query.
func (h *placementHandler) listPlacements(c *gin.Context) {
	values, err := url.ParseQuery(c.Request.URL.RawQuery)
	if err != nil {
		writeAPIError(c, http.StatusBadRequest, codeInvalidInput, "invalid placement query")
		return
	}

	result, err := h.svc.Query(c.Request.Context(), values)
	if errors.Is(err, service.ErrInvalidPlacementQuery) {
		writeAPIError(c, http.StatusBadRequest, codeInvalidInput, "invalid placement query")
		return
	}
	if errors.Is(err, service.ErrPlacementNotFound) {
		writeAPIError(c, http.StatusNotFound, codeNotFound, "placement not found")
		return
	}
	if err != nil {
		writeAPIError(c, http.StatusServiceUnavailable, codeStorageDown, "database is not available")
		return
	}
	if result.Record != nil {
		c.JSON(http.StatusOK, result.Record)
		return
	}
	c.JSON(http.StatusOK, gin.H{"items": result.Items})
}

package service

import (
	"context"

	"github.com/Bob-xisuke/orb-scheduler-core/internal/model"
)

// Store is the persistence contract Accept, Query and the HTTP health
// probe rely on. The production implementation is the SQLite-backed
// *store.Store; tests can substitute an in-memory double (see
// internal/service/fakestore) that controls the returned records and
// errors without creating a database file. Either way the business flow
// — defaults, trial scheduling, idempotency and conflict rules, query
// validation — stays in this package and is never re-implemented by the
// storage side. The contract speaks only in model types, so implementing
// it never requires a SQLite driver.
type Store interface {
	// Ping reports whether the storage layer is usable. The health route
	// answers from it alone; a failing Ping must not change or inspect any
	// stored record.
	Ping(ctx context.Context) error
	// Submit stores p the first time its (namespace, name) identity is seen
	// and reports created; on a repeated identity it returns the previously
	// stored record with created false and changes nothing.
	Submit(ctx context.Context, p *model.Placement) (stored *model.Placement, created bool, err error)
	// Get fetches one record by identity, returning model.ErrNotFound when
	// the identity is unknown.
	Get(ctx context.Context, namespace, name string) (*model.Placement, error)
	// List returns the committed records matching f, sorted by namespace
	// then name in UTF-8 byte order; a node filter never matches a rejected
	// record.
	List(ctx context.Context, f model.ListFilter) ([]*model.Placement, error)
}

package api

import (
	"net/http"

	"github.com/gin-gonic/gin"

	"github.com/Bob-xisuke/orb-scheduler-core/internal/service"
)

// NewRouter wires the public HTTP surface: health and the placements API.
// It depends only on the service.Store contract: production wires the
// SQLite-backed *store.Store, tests can wire an in-memory double without
// creating a database file. Constructing a router never probes, opens or
// closes storage; lifecycle stays with the value the caller passes in.
// Every entry keeps the error shape described in README.md.
func NewRouter(st service.Store) *gin.Engine {
	gin.SetMode(gin.ReleaseMode)
	router := gin.New()
	router.Use(gin.Recovery())

	router.GET("/healthz", func(c *gin.Context) {
		if err := st.Ping(c.Request.Context()); err != nil {
			c.JSON(http.StatusServiceUnavailable, gin.H{"error": gin.H{"code": "storage_unavailable", "message": "database is not available"}})
			return
		}
		c.JSON(http.StatusOK, gin.H{"status": "ok", "database": "ok"})
	})

	h := &placementHandler{svc: service.New(st)}
	router.POST("/v1/placements", h.createPlacement)
	router.GET("/v1/placements", h.listPlacements)

	router.NoRoute(func(c *gin.Context) {
		c.JSON(http.StatusNotFound, gin.H{"error": gin.H{"code": "route_not_found", "message": "no route matches this path"}})
	})
	return router
}

package store

import "github.com/Bob-xisuke/orb-scheduler-core/internal/model"

// Compatibility re-exports. The record model, the defaulting and
// content-equality rules, and the storage-contract vocabulary live in
// internal/model so that parsing, scheduling and idempotency judgment — and
// in-memory storage doubles — never depend on this package's SQLite driver.
// Existing callers that refer to these names through package store keep
// working unchanged: the aliases are the very same types and functions.

type (
	// Placement is one stored scheduling decision; see model.Placement.
	Placement = model.Placement
	// Node is one candidate node offered by a placement request.
	Node = model.Node
	// Resources is a workload request or a node capacity.
	Resources = model.Resources
	// ListFilter narrows List; empty fields are ignored. Node never matches
	// a rejected record.
	ListFilter = model.ListFilter
)

// ErrNotFound is returned by Get when no placement matches the identity.
var ErrNotFound = model.ErrNotFound

// NormalizeInput fills the documented omitted-field defaults in place; see
// model.NormalizeInput, the single definition shared by every entry point.
var NormalizeInput = model.NormalizeInput

// SameInput reports whether the request halves of two placements are equal
// under the documented comparison; see model.SameInput.
var SameInput = model.SameInput

// Package model holds the pure business definitions of the placement
// service: the record model every layer shares, the single definition of
// input defaulting and content equality, and the storage-contract vocabulary
// (ErrNotFound, ListFilter). It imports nothing beyond the standard library —
// in particular no SQLite driver and no connection management — so input
// parsing, trial placement and idempotency judgment can depend on it without
// pulling in any storage implementation. The SQLite-backed store in
// internal/store is one consumer of these definitions; in-memory storage
// doubles are another.
package model

import "errors"

// Resources is a workload request or a node capacity. CPU is in millicores and
// memory in MiB; both are non-negative 64-bit integers on the wire.
type Resources struct {
	CPU    int64 `json:"cpu"`
	Memory int64 `json:"memory"`
}

// Node is one candidate node offered by a placement request.
type Node struct {
	Name   string            `json:"name"`
	CPU    int64             `json:"cpu"`
	Memory int64             `json:"memory"`
	Labels map[string]string `json:"labels"`
}

// Placement is one stored scheduling decision: the request payload plus its
// status. Node and Reason are pointers so a rejected record renders them as
// JSON null.
type Placement struct {
	Namespace string            `json:"namespace"`
	Name      string            `json:"name"`
	Queue     string            `json:"queue"`
	Priority  int32             `json:"priority"`
	Resources Resources         `json:"resources"`
	Selector  map[string]string `json:"selector"`
	Nodes     []Node            `json:"nodes"`
	Status    string            `json:"status"`
	Node      *string           `json:"node"`
	Reason    *string           `json:"reason"`
}

// ErrNotFound is returned by a store's Get when no placement matches the
// identity. It is part of the storage contract shared by every Store
// implementation, not of any one storage engine.
var ErrNotFound = errors.New("placement not found")

// ListFilter narrows a store's List; empty fields are ignored. Node never
// matches a rejected record.
type ListFilter struct {
	Namespace string
	Queue     string
	Node      string
}

